import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { verifyBundle } from "../src/bundle.js";
import { verifyRecordSignature } from "../src/producer-envelope-verification.js";

// Strict verifyBundle against vectors/bundle/strict (generated by
// python/scripts/generate_bundle_strict_vectors.py), compared exactly as its
// README says and python/tests/test_bundle_strict_vectors.py does.
const DIR = resolve(process.cwd(), "..", "vectors", "bundle", "strict");

type Case = {
  id: string;
  options: { require_signature: boolean; witness_directory: boolean };
  bundle: unknown;
  expect: Record<string, unknown>;
};
const vectors = JSON.parse(
  readFileSync(resolve(DIR, "vectors.json"), "utf8"),
) as {
  witness_directory: unknown;
  cases: Case[];
  record_signatures: { id: string; record: unknown; expect: string }[];
};
const manifest = JSON.parse(
  readFileSync(resolve(DIR, "manifest.json"), "utf8"),
) as { case_count: number; record_signature_count: number };

describe("strict Evidence Bundle vectors", () => {
  it("runs every case the manifest counts", () => {
    expect(vectors.cases).toHaveLength(manifest.case_count);
    expect(vectors.record_signatures).toHaveLength(
      manifest.record_signature_count,
    );
  });

  const checkCase = async (_id: string, testCase: Case): Promise<void> => {
    const result = await verifyBundle(testCase.bundle, {
      strict: true,
      requireSignature: testCase.options.require_signature,
      ...(testCase.options.witness_directory
        ? { witnessDirectory: vectors.witness_directory }
        : {}),
    });
    const strict = result.strict;
    expect({
      verdict: strict.verdict,
      kind_ok: strict.kindOk,
      claims: strict.claims.map(({ name, status, findings }) => ({
        name,
        status,
        findings,
      })),
      witnesses:
        strict.witnesses === null
          ? null
          : {
              status: strict.witnesses.status,
              findings: strict.witnesses.findings,
              receipts: strict.witnesses.receipts.map((r) => ({
                ts_url: r.tsUrl,
                binding: r.binding,
                status: r.status,
                grade: r.grade,
                key_id: r.keyId,
                registration_time: r.registrationTime,
                registration_time_reason: r.registrationTimeReason,
              })),
            },
      records: strict.records.map((r) => ({
        capsule_id: r.capsuleId,
        identity_ok: r.identityOk,
        signature: r.signature,
        key_id: r.keyId,
        seq: r.seq,
      })),
      checkpoint_authenticated: strict.checkpointAuthenticated,
      signer_matches_checkpoint: strict.signerMatchesCheckpoint,
    }).toEqual({ kind_ok: true, ...testCase.expect });
    // The strict claims are the result's own claims where they overlap.
    const claim = (name: string) => strict.claims.find((c) => c.name === name);
    if (strict.kindOk) {
      expect(claim("interval_coverage")).toMatchObject(result.intervalCoverage);
      expect(claim("per_record_membership")).toMatchObject(
        result.perRecordMembership,
      );
      expect(strict.signedCheckpoint !== undefined).toBe(
        strict.checkpointAuthenticated,
      );
    }
  };

  it.each(vectors.cases.map((c) => [c.id, c] as const))("%s", checkCase);

  it.each(vectors.record_signatures.map((c) => [c.id, c] as const))(
    "record signature %s",
    async (_id, testCase) => {
      const { verdict, messages } = await verifyRecordSignature(
        testCase.record,
      );
      expect(verdict).toBe(testCase.expect);
      expect(messages.length > 0).toBe(verdict === "invalid");
    },
  );

  it("reads signature and key_id as hex digit pairs only", async () => {
    const authored = vectors.record_signatures.find(
      (c) => c.id === "authored-jcs",
    )!.record as Record<string, string>;
    // Either case is the same key and envelope.
    expect(
      (
        await verifyRecordSignature({
          ...authored,
          signature: authored.signature!.toUpperCase(),
          key_id: authored.key_id!.toUpperCase(),
        })
      ).verdict,
    ).toBe("authored");
    for (const edit of [
      { signature: ` ${authored.signature}` },
      {
        key_id: `${authored.key_id!.slice(0, 2)} ${authored.key_id!.slice(2)}`,
      },
      { key_id: "" },
      { signature: 5 },
    ])
      expect(
        (await verifyRecordSignature({ ...authored, ...edit })).verdict,
      ).toBe("invalid");
  });

  it("holds only the first of two records with one capsule_id", async () => {
    const bundle = structuredClone(vectors.cases[0]!.bundle) as {
      records: { capsule_id: string }[];
    };
    const first = bundle.records[0]!;
    bundle.records.push(structuredClone(first));
    const { strict } = await verifyBundle(bundle, { strict: true });
    const copies = strict.records.filter(
      (r) => r.capsuleId === first.capsule_id,
    );
    expect(copies.map((r) => r.identityOk)).toEqual([true, false]);
    expect(strict.claims.find((c) => c.name === "records")).toMatchObject({
      status: "fail",
      findings: [`record_identity_invalid:${first.capsule_id}`],
    });
  });

  it("refuses a Bundle that is not a JSON object", async () => {
    for (const bundle of [null, [], "bundle", 2]) {
      const { strict } = await verifyBundle(bundle, { strict: true });
      expect(strict).toMatchObject({
        verdict: "INVALID",
        kindOk: false,
        claims: [{ name: "records", findings: ["not_an_evidence_bundle_v2"] }],
        witnesses: null,
      });
    }
  });

  it('reports a capsule_id that is not a string as ""', async () => {
    const bundle = structuredClone(vectors.cases[0]!.bundle) as {
      records: Record<string, unknown>[];
    };
    bundle.records[0]!.capsule_id = 5;
    const { strict } = await verifyBundle(bundle, { strict: true });
    expect(strict.records[0]!.capsuleId).toBe("");
    expect(strict.verdict).toBe("INVALID");
  });

  it("lists unknown memberships in sorted Capsule ID order", async () => {
    const selected = vectors.cases.find(
      (c) => c.id === "incomplete-producer-selected",
    )!;
    const bundle = structuredClone(selected.bundle) as {
      completeness_certificate: { memberships: Record<string, unknown> };
    };
    const memberships = bundle.completeness_certificate.memberships;
    for (const id of ["f".repeat(64), "a".repeat(64), "c".repeat(64)])
      memberships[id] = {};
    const { strict } = await verifyBundle(bundle, { strict: true });
    expect(
      strict.claims
        .find((c) => c.name === "per_record_membership")!
        .findings.filter((f) => f.startsWith("membership_record_unknown:")),
    ).toEqual(
      ["a", "c", "f"].map((c) => `membership_record_unknown:${c.repeat(64)}`),
    );
  });

  // pos-witness-cll with its unprotected proof blob [1, 0, []] (83 01 00 80)
  // re-encoded: unsigned, so only the decoding rule decides the receipt.
  const withProofBlob = async (blobHex: string) => {
    const testCase = vectors.cases.find((c) => c.id === "pos-witness-cll")!;
    const bundle = structuredClone(testCase.bundle) as {
      checkpoint: { witnesses: { receipt_b64: string }[] };
    };
    const receipt = bundle.checkpoint.witnesses[0]!;
    const original = Buffer.from(receipt.receipt_b64, "base64").toString("hex");
    expect(original.split("4483010080")).toHaveLength(2);
    // A byte string of fewer than 24 octets: its length is in the head.
    const octets = blobHex.length / 2;
    expect(octets).toBeLessThan(24);
    receipt.receipt_b64 = Buffer.from(
      original.replace(
        "4483010080",
        `${(0x40 + octets).toString(16)}${blobHex}`,
      ),
      "hex",
    ).toString("base64");
    const { strict } = await verifyBundle(bundle, {
      strict: true,
      requireSignature: testCase.options.require_signature,
      witnessDirectory: vectors.witness_directory,
    });
    return { strict, expected: testCase.expect.verdict };
  };

  // The receipt encoding rule holds inside the blob as in the envelope.
  it.each([
    ["non-shortest integer heads", "831801180080"],
    ["an indefinite-length outer array", "9f010080ff"],
    ["an indefinite-length path", "8301009fff"],
    ["both indefinite", "9f01009fffff"],
    ["trailing bytes after the array", "83010080ff"],
    ["an unterminated indefinite array", "9f010080"],
    ["a break inside a definite array", "830100ff"],
    ["a path of a non-byte-string", "8301009f01ff"],
  ])("refuses an inclusion-proof blob with %s", async (_name, blobHex) => {
    const { strict } = await withProofBlob(blobHex);
    expect(strict.witnesses).toMatchObject({ status: "fail" });
  });

  it("leaves the plain result unchanged", async () => {
    const bundle = vectors.cases[0]!.bundle;
    const plain = await verifyBundle(bundle);
    expect(plain.strict).toBeUndefined();
    const strict = await verifyBundle(bundle, { strict: true });
    const { strict: _strict, ...rest } = strict;
    expect(rest).toEqual(plain);
  });
});
